    --                             · 「已读字数」需要的每页归属，改为按宽度均分
    --                               （总字数精确，页间分配是估算）。
    --   24-cache-reuse         ★★★ 修掉「统计完还要每次重新统计」：
    --                           根因 —— `startCount` / `startCountForPath`
