    --   (3)「亿万字的书还是统计不成功，显示无法打开文件」—— 两个真 bug：
    --       · **返回值丢失**：`pcall(openPreparedDocument, path)` 只取第一个返回
    --         值，而巨书时函数返回的是 `(nil, "huge_document")` ⇒ 第二个返回值
    --         （错误原因）被丢掉 ⇒ `doc == "huge_document"` 永不成立 ⇒ 用户
    --         看到的是**误导性的通用文案**「无法打开文件：nil」。三处调用点
