    --         页数」就直接拒绝统计。但日志显示**同一本 219MB 的书有时
    --         loadDocument 后能拿到 pageCount=93551**（crengine 惰性分页不稳定）。
    --         ⇒ 改为：巨书**重试 loadDocument 若干次**（仍**绝不 render**，render
    --         才是吃 130MB / OOM 的那步），拿到页数就放行（startCount 会因
