    --       **从不 close 那本文档** ⇒ 每次早退漏一本，批量反复触发即 OOM。
    --       修：抽出 `close_override_doc()`，四条早退路径全部调用；
    --       判据与 `refuse_reason` 分支一致（**绝不关「用户正在读」的那本**）。
