    -- ★★★ 1.6（用户原话：「为什么会跳过两本，书籍大小很小啊」）
    --
    --   用户的直觉是对的：**跳过与书的大小完全无关**。批量里「跳过」有 4 条
    --   独立入口，其中 **3 条在 1.6 之前是完全静默的** —— 用户只看到汇总的
