    -- ★★★ 1.0（正式发布）
    --
    --   版本号定为 **1.0**：这是本插件对外发布的第一版。
    --
    --   为什么从 1.9 回到 1.0：上面 1.1 ~ 1.9 是**开发过程中的内部迭代号**
    --   （每修一批 bug 就 +0.1），一路涨到 1.9 只是「改了多少轮」的计数，
    --   不是对外版本语义。用户反馈「版本号一直变、分不清哪个是正式版」，
    --   所以这里收敛成 1.0 —— 从此 **只有对外发版才动这个号**。
    --
    --   上面 1.1 ~ 1.9 的记录**原样保留**，作为改动溯源（排查老问题时能对上
    --   用户当时装的是哪一轮）。
