    --   ⚠ 以后发版只改两处：本行的 version + run_tests.py 的 VERSION/VARIANT。
    --     `run_tests.py --pack` 会校验 zip 里的 `version = "..."` 与 VARIANT 一致，
    --     改漏一处直接报错。
