    --
    -- ★★★ 1.1 内修订（跳章节导致「已读字数 / 阅读速度」虚高）
    --
    --   ⚠ **不升版号**：版本号由用户决定，改代码一律不动它。
    --     （用户约定：「每次改的时候我不说就不要更新版本号」）
    --
    --   用户原话：「关于字数的统计，当从某一章节跳另一章节的时候，
    --             中间未阅读的部分也会计算进去并且也会计算到阅读速度里」。
    --
    --   ★ 先看**设备上的真实数据**（settings.reader.lua 的
    --     word_count_global_stats_v1，383 本里有 14 本带已读数据）：
    --       普通人，但怪物之母 - 西风醉 (884).epub
    --         全书 1530202  已读 1530695  27 秒  2 页  速度 3401544 字/分
    --     ⇒ **只读了 2 页，却记成了整本书的 100%**。这就是用户看到的现象。
    --
    --   ★ 根因链（三个独立缺口，缺一个都不会这么严重）：
    --
    --     ① **结算时用失效的页映射去抽「本页文本」**（主因）。
    --        `_finishPageTimer` 里 `_getPageUnits(doc, page, ...)` →
    --        `PageText.extract` → `crePageText` 用
    --        `getPageXPointer(page)` / `getPageXPointer(page+1)` 当区间两端。
    --        而 **page_text.lua 自己的开头注释就写了**：crengine 会把页边界
    --        **吸附到元素/文本节点边界**，于是 page+1 的 xpointer 可能
    --        **不大于** page 的（相等或逆序），此时 `getTextFromXPointers`
    --        会返回「空串或**整段**」。
    --        对「一章 = 一个文本节点」的书（网文 TXT 转 EPUB 极常见），
    --        那个「整段」就是**整章** ⇒ 一页被记成几千上万字。
    --        旧代码对这条路径**没有任何校验**（既不看区间是否单调，
    --        也不看取回的文本有多长），抽到多少就记多少。
    --
    --     ② **部分重排后继续按页码记账**（放大器）。
    --        `onDocumentPartiallyRerendered` 旧实现是「拿失效的
    --        `pageCount(doc)` 重建阅读状态 + 重启计时」——
    --        正好把①推到了最容易出错的时刻。
    --        上游 `readerrolling.lua` 的 `handleRenderingDelayed()` 里写得很清楚：
    --          「Pages and ToC will be invalid, some modules may want to
    --            disable some features (ie. **reading statistics should stop
    --            accounting pages read/total pages, as there are invalid,
    --            and bogus data would stick in the stats db**)」
    --        上游 `statistics.koplugin` 的做法就是在那里**彻底停掉页记账**
    --        （覆写 onPageUpdate 直接 return）。本插件反着来。
    --
    --     ③ **没有「已读 ≤ 全书」这条不变式**（兜底缺失）。
    --        `recompute` 只是把 `page_seconds` 里各页的 `page_units` 加起来，
    --        没有任何上界。于是①/②留下的错值会**长期固化**进
    --        sidecar 与 KEY_GLOBAL_STATS —— 用户不重置设置就再也回不来。
    --
    --   ★ 修法（四层，每层都能独立拦住一类退化）：
    --
    --     L1 `page_text.lua`：**页区间单调性闸门**。
    --        调 `getTextFromXPointers` 之前先 `compareXPointers(start, end)`，
    --        只有返回 1（end 严格在 start 之后）才继续；
    --        返回 0 / -1 ⇒ 直接 `return nil`，**绝不退到下面
    --        「返回整段文本节点」的兜底**（那正是虚高的来源）。
    --        同时给三条抽取路径都加**字节闸门** `MAX_PAGE_TEXT_BYTES = 60000`
    --        （≈2 万汉字，6 吋屏一页的物理上限）：超长的一律判不可信。
    --        附带收益：不再把几 MB 的字符串喂给计数器 —— 省 CPU/省电。
    --
    --     L2 `main.lua`：**单页字数钳制** `_pageUnitsBounds`。
    --        `cap = max(PAGE_UNITS_MIN_CAP, 全书页均值 × PAGE_UNITS_MAX_FACTOR)`
    --        = max(4000, 均值×3)。计数**之前**先按 `#text > cap*4` 字节粗筛；
    --        抽到的字数 > cap 也判不可信。
    --        不可信时**退回「全书页均值」并打估算标记**（不记 0，也不记那个大值）：
    --          · 记 0 → 已读字数明显偏低，用户照样觉得不对；
    --          · 打估算标记 → 后续能抽到真实值的页会覆盖它（复用
    --            30-estimate-shadow-fix 的机制），逐页精度还能自己回来。
    --
    --     L3 `main.lua`：**页映射失效时停止页记账**（对齐上游）。
    --        `onDocumentPartiallyRerendered(true)` →
    --        先把当前页 `_finishPageTimer(false, true)`（**只记时间、不抽文本**，
    --        那一页的时间是真读掉的，不该丢）→ 置 `_pagemap_invalid`。
    --        之后 `_trackPageUpdate` / `_startPageTimer` 一律早退。
    --        `onReaderReady`（换书）重置该闸门。
    --        取舍与上游一致：**宁可少记，不可记假。**
    --
    --     L4 `reading_stats.lua`：**「已读 ≤ 全书」硬不变式**。
    --        全书字数存进 `state.total_units`（`_ensureReadState` /
    --        `_syncGlobalBook` 维护），`recompute` 里把 units 钳到它以内 ——
    --        这条闸门与机制无关，将来再冒出未知的退化路径也拦得住。
    --        `_syncGlobalBook` 里先钳再 upsert，避免错值先固化进全局统计。
    --
    --   ★ 验证（无设备；fengari + **真实源码切片**，`_verify/jump.lua`）：
    --     不重写逻辑 —— `reading_stats.lua` / `page_text.lua` / `word_count.lua`
    --     直接 load 真实文件，`_getPageUnits` / `_finishPageTimer` /
    --     `_startPageTimer` / `_trackPageUpdate` / `_ensureReadState` /
    --     `onDocumentPartiallyRerendered` 全部从真实 main.lua 按源码切片抽出来跑；
    --     只对磁盘/UI/全局统计打桩。
    --     mock doc 模拟「一章 = 一个文本节点、一章排 100 页」的书
    --     （全书 800 页 / 40 万字，页均值 500 字），跳章节时页边界被吸附到章首。
    --
    --     **修复前（负向对照，13 条 FAIL）**：
    --       · 只读 1 页、跳一次章节 → 已读 **50000 字**（= 整章）、
    --         速度 **100000 字/分**（真值应是 500 字 / 1000 字/分）；
    --       · 部分重排后再翻 5 页 → 已读再涨 **100000 字**；
    --       · 投毒「单页=全书×2」→ recompute 原样输出 **800000 > 全书 400000**。
    --
    --     **修复后（全绿）**：
    --       · 同一场景 → 已读 **500 字**、速度 **1000 字/分**（正好一页）；
    --       · 部分重排后再翻 5 页 → 已读**不再增长**；
    --       · 投毒 → 被钳到 **400000 = 全书字数**；
    --       · 回归：**正常页映射**下连读 10 页仍记 5000 字（没被误伤）。
    --
    --     另外原有 18 条 sorting_hint 回归断言（1.1 的修复）全部仍然通过；
    --     静态扫描：语法错 0、未声明变量 0、多字节字符类告警 0。
    --
    --   ★ 用户可自查：设备上「字数与阅读速度」菜单顶部那行应显示 `版本：1.1`。
    --
    -- ★★★ 1.1 内修订（阅读统计页 · 「趋势图看不懂」+「术语和单位混乱」）
    --
    --   ⚠ 同样**不升版号**。
    --
    --   用户原话：「优化阅读统计页面，不够直观」，勾选的是
    --             「趋势图看不懂」+「术语和单位混乱」。
    --
    --   ★ 趋势图 —— 三个**独立的**原因（都是读代码读出来的，不是猜的）：
    --
    --     ① X 轴刻度**按 period 现造**，与 bucket.label 是两套（真 bug）。
    --        旧 `trendBucketLabels(period, count)` 自己生成刻度：
    --          | 粒度 | 真实 bucket.label          | 旧刻度 | 后果 |
    --          |------|----------------------------|--------|------|
    --          | 日   | "00".."23"（**每小时一根**）| 0..23  | 看着像「日期」，其实是小时 |
    --          | 周   | 一..日                      | 一..日 | ✓ |
    --          | 月   | "01".."31"                  | 1..31  | 丢前导零 |
    --          | 年   | "01月".."12月"              | 1..12  | **丢了「月」** |
    --          | 累计 | "25年10月" 这种              | 1..12  | **完全看不出是哪年哪月** |
    --        更糟的是：**列表视图用的是 bucket.label（正确）** ⇒ 同一份数据在
    --        「图表」和「列表」两个视图里 X 轴含义不一致，来回切一下就对不上。
    --        修法：删掉 `trendBucketLabels`；`buildTickRow` 改收 `buckets`、
    --        直接用 `bucket.label`。抽稀逻辑不变，只是量的是**真实刻度文本**
    --        的宽度（"25年10月" 比 "1" 宽得多，累计视图会自动少标几个 ——
    --        这正是抽稀该干的事）。
    --
    --     ② 图里**没有任何参照**，看不出「我这样算读得多还是少」。
    --        修法：加一条**黑色均值虚线**（12px 长划 + 8px 空），并在图下
    --        补一行图例「点柱子看具体数值 · 虚线＝本期平均 X」。
    --        · 线型必须与网格线**在形状上**区分（网格 = 4px 短点线 LIGHT_GRAY）
    --          —— e-ink 没有颜色层次可用，只能靠线型。
    --        · 虚线画在**柱子之后**（压在最上层）：柱间空隙只占 slot 的 20%，
    --          画在柱子下面会被盖掉大半、根本连不起来。
    --        · **口径**：只平均 value > 0 的桶，跳过 0 的桶。这不是随手定的 ——
    --          必须与 `GlobalStats.summarize` 的「日均阅读时长」完全一致
    --          （`result.days` 只在 sec > 0 时 +1），否则同一页上卡片和虚线
    --          会用两个分母，用户一算就发现对不上。副作用正是想要的：
    --          月视图只读了 4 天时，虚线落在「读过的那些天的平均水平」，
    --          而不是贴在地板上（除以 31 的话就会）。
    --        · 已知取舍：黑虚线压在**选中的那根黑柱**上时看不见。只有一根柱子
    --          如此，其余灰柱/白底上都能连起来，整体仍可读 ——
    --          不值得为此引入白描边（会破坏「全实心柱」的观感）。
    --
    --     ③ **值为 0 的桶也照标数值**（噪音太多）。
    --        月视图 31 桶、日视图 24 桶，通常只有几天/几个小时真读过书；
    --        旧 `chartValueLabels` 对 0 值桶照样摆标签 ⇒ 底部糊上一整排
    --        「0秒」，把真正有数的三四根柱子彻底淹掉。
    --        修法：新增 `has_value(i)` 守卫，**值为 0 的桶不标**。
    --        · 这不是推翻 37s 那条「每根柱子都标上」—— 0 值桶**根本没有柱子**
    --          （barPixelHeight 返回 0，不画），给它标 0 不在那条要求的范围内。
    --          周视图 7 根全有值时依旧 7 个标签全在（有断言守着）。
    --        · 跳过时**不动 left_edge / right_edge** —— 那两个记的是「已放置
    --          标签的边沿」，被跳过的桶什么都没放，不能拿它的位置去收紧
    --          后面（更靠外）的判定，否则会把本来放得下的标签误判成重叠。
