    --   ★ 术语/单位 —— 用户可见文案里的「单位」全部改成「字」：
    --     · `main.lua` 全书统计完成的通知：「平均 %3 单位/分钟」→「字/分钟」
    --       （统计页的卡片/坐标轴/页脚一律是「字/分钟」，同一个量两种叫法）。
    --     · `bookshelf_integration.lua` 三个 token 描述：
    --       "reading units" → "words per minute" /
    --       "Word count on pages actually read"。
    --     · **有意保留** `main.lua` 的「单位显示：%1」—— 那是本插件给
    --       「万 / k / 千」这个**数字格式**设置起的名字，跟「字数单位」是两码事，
