    --      `compactTickLabels()`，只在**年份变化的那一格**保留年份：
    --          11月 12月 26年01月 02月 03月 … 10月
    --      ★ 三个刻意取舍（都写进注释了，免得以后被当 bug 改掉）：
    --        · **第一格也不留年份** —— 用户说的是「只有…过渡的年份」，
