    -- ★★★ 42-round-dot —— **列表分隔线：方横条 -> 真圆点**
    --   （用户原话：「分隔线密集一点，不是圆点吗，怎么都是方的」）
    --
    --   ① 先把**换算**说清楚 —— 这是前几轮一直算错的地方，值得单列：
    --      KOReader 的实现在 `ffi/framebuffer.lua:414`：
    --          scaleBySize(px) = ceil(px * (size_scale + dpi_scale) / 2)
    --          size_scale = min(屏宽, 屏高) / 600
    --          dpi_scale  = size_scale      -- 没设 `screen_dpi` 覆盖时两者相等
    --      ⇒ **scaleBySize(px) = ceil(px * min(W, H) / 600)**
    --      KPW4 是 1072×1448（crash.log 里 `initializing for device
    --      KindlePaperWhite4` 紧跟着就是 w=1072 / h=1448），settings 里
    --      没有 `screen_dpi` ⇒ 系数 1072/600 = 1.78667，并且**向上取整**：
    --          scaleBySize(1)=2  (2)=4  (3)=6  (4)=8  (5)=9  (10)=18
    --      ⚠ 不是 `floor(n * 1.875)` —— 那是按 300dpi 直接折算，KOReader
    --        不这么算。41 轮的注释和预览图都按 1.875 算，把 4px 宽的点
    --        当成 3px，整条结论偏了一档 —— 这也正是「改了长短还是方的」
    --        没被当场发现的原因。
    --      ⇒ 41 轮之后那条线的真实尺寸其实是 **4px 宽 × 2px 高、间隔 8px、
    --        周期 12px**：宽高比 2:1 的扁横条，在 300dpi 上就是一排小方块。
    --
    --   ② 改法（**只动 `HRule` 一个控件，3 个调用点一行没改**）：
    --      · 新增模块常量 `SEP_DOT_R = 2`、`SEP_DOT_GAP = Screen:scaleBySize(2)`；
    --      · `HRule` 新增 `dot_r`（类默认值 = SEP_DOT_R）与 `dot_gap`；
    --      · dotted 分支改用 `bb:paintCircle(x+px, cy, r, color)`
    --        （`ffi/blitbuffer.lua:1948`，`w` 默认 = `r` ⇒ 实心）。
    --      ⚠ 半径 1（3px）的光栅是**十字**（1/3/1），不是圆
    --        ⇒ 最小可用半径就是 2；半径 3（7px）最圆，但要 7px 行高 ⇒ 掉行。
    --      ⚠ **行高（height）故意不动**，仍是 `scaleBySize(1)` = 2px：
    --        `rows_per_page = avail / (row_h + line_w)`，按本文件常量推算
    --        KPW4 上 avail≈715 ⇒ 715/74=9.66、715/77=9.28 都还是 9 行，
    --        715/80=8.94 就掉到 8 行。多出来的 ±2px 溢到相邻行的**空白**里：
    --        列表行 / 浮窗行是透明 FixedBox，卡片那处下方是 9px 的 cell_gap，
    --        且这些容器都不 setClipRect ⇒ 既不盖字，也不会被后画的擦掉。
    --      ⇒ 结果：**5px 实心圆点 + 4px 间隔 = 周期 9px**，比 12px 密 25%。
    --      ⚠ 保留 `dot_r = 0` 回退到旧的横条实现（`dot_len` / `gap_len` 仍在）。
    --      ⚠ 间隔别调到 3px 以下（相邻点会粘连成「串珠」）。
