    -- ★★★ 42b —— **用户说「看看是否有bug」后的自查**（只补防呆 + 改注释，不动观感）
    --
    --   ① 找到 3 个问题，其中 1 个是**真 bug**、2 个是**地雷**：
    --      · 【真 bug，已修】右边界 off-by-one。
    --        `while px + r <= size.w` —— `paintCircle` 点亮的列是
    --        `px-r .. px+r`，而控件占的列是 `0 .. size.w-1`，所以必须
    --        `px + r <= size.w - 1`（即 `< size.w`）。写成 `<=` 时，
    --        凡 `size.w ≡ 4 (mod 9)` 的宽度都会**右溢 1px**。
    --        实测会触发的宽度：4, 13, 22, 31, 40, 49, 58, …（差 9）
    --        ⇒ 真实三处宽度 950 / 821 / 310 里，**310（卡片样式那条）会踩**，
    --        950 / 821 恰好不踩（点数仍分别是 106 / 91，改前改后一致）。
    --      · 【地雷，已加防呆】`dot_gap` 传负值 ⇒ `step = 2r+1+gap <= 0`
    --        ⇒ 下面那个 `while` **死循环**（已用 fengari 复现：
    --        gap=-7 时 step=-2，跑满 1000 次迭代 px 从 2 跑到 -1998 仍不退出）。
    --        当前无调用点会传负值，但 `dot_gap` 是公开字段，不该留这种雷。
    --        改成 `math.max(0, self.dot_gap or SEP_DOT_GAP)`。
    --      · 【地雷，已加防呆】`dot_r` 传小数（如 2.9）⇒ `paintCircle` 内部
    --        `setPixelClamped(cx, cy+tmp_y)` 拿到非整数坐标 ⇒ FFI 索引报
    --        「number has no integer representation」。改成 `math.floor(...)`。
    --   ② **注释算错了一处**（这条比 bug 本身更值得记）：
    --      statistics_page.lua 里原写「把 line_w 从 2 抬到 5 会让 KPW4 上每页
    --      从 9 行掉到 8 行」—— **错的**。按本文件常量复算：
    --          竖屏 avail=715, row_h=72 ⇒ 2px: 715/74=9.66→9 行
    --                                    5px: 715/77=9.29→**还是 9 行**
    --          横屏 avail=376, row_h=72 ⇒ 2px: 376/74=5.08→5 行
    --                                    5px: 376/77=4.88→**掉到 4 行**
    --      ⇒ 「不抬行高」的真正理由是**横屏**掉行，不是竖屏。结论没变
    --      （行高仍 2px），但依据已更正，免得下次有人照着错依据去改。
    --   ③ 顺带核过的、**确认无问题**的点（免得下次重复查）：
    --      · 圆点比声明高度多画 ±2px，**没有任何东西会擦掉它**：
    --        全 KOReader 树 `setClipRect` 出现 **0 次**（唯一近似裁剪是
    --        ScrollableContainer 把子控件画到白画布再 blit 一块，而分隔线
    --        在容器 dimen 之内；阅读字数列表页更是不用滚动容器）；
    --        列表行都是透明 FixedBox（不画底色），「点线」卡片那处的行间距
