    -- ★★★ 43 —— **周期选择器重做 + 3 个渲染/刷新 bug**（用户 4 条一起提的）
    --
    --   用户原话：
    --     「阅读统计里的日周月年以及总览选择能不能重新弄好（年的点击可以选择年份，
    --       月的点击可以选择月份，日的点击可以选择月份，周的点击可以选择第几周
    --       （第几周后面跟着时间）），柱子不显示12月的，以及点击阅读字数去世后就
    --       没办法返回柱状图形式了，日周切换的时候年月日总会出现一个黑框然后消失。」
