    --
    --   4 条里 1 条是功能缺失、3 条是 bug；另外追问确认了 4 个细节：
    --   12 月缺的是**刻度标签**不是柱子 / 两条路径都回不去 / 黑框在
    --   「2026年」「10月12日」那两行 / 点**已选中**的标签才弹选择器。
    --
    --   ① 【功能】周期选择器 —— 原来只有「切粒度」，没有「选具体哪一期」。
    --      改法：标签变成**两级语义** ——
    --        · 点**未选中**的标签 ⇒ 只切粒度，**保留当前 anchor**
    --          （旧代码写死 `anchor = os.time()`，一切就跳回今天）；
    --        · 点**已选中**的标签 ⇒ 弹该粒度的选择器。
    --      新增 3 个选择器（都在 statistics_page.lua 的 `★★★ 43-pickers` 段）：
    --        · `showPeriodPicker(granularity)` 分派：year→年 / month,day→月 /
    --          week→周 / total→不弹（总览没有「哪一期」的概念）。
    --        · `showMonthPicker(target_period)` —— 竖向 ButtonDialog，
    --          数据来自新的 `GlobalStats.availableMonths`，当前月份行尾标 `" ✓"`。
    --        · `showWeekPicker()` —— 竖向 ButtonDialog，
    --          每行是 `第41周  10月05日–10月11日`（**周号后面跟日期区间**，
    --          正是用户要求的「第几周后面跟着时间」），
    --          数据来自新的 `GlobalStats.availableWeeks`。
    --      另外第 2 行那两行文字（「2026年」「10月12日」）原来点一下会
    --      `cycleToGranularity("day")`（一路下钻到日），现在改成弹**当前粒度**的选择器。
    --
    --      ★ 踩到的坑：`GlobalStats.shiftAnchor("month", anchor, delta)` 内部
    --        写死 `dayTimestamp(y, m + delta, 1)` —— **日被硬编成 1**，
    --        拿它做「跳到某个月且保留当前日」会把日期重置到 1 号。
    --        所以没复用它，另写了 `anchorAtMonth(anchor, year, month)`：
    --        保留日，超出目标月天数时夹到月末（如 31 号 → 2 月 28/29 号）。
    --
    --   ② 【bug】累计视图 X 轴缺「12月」刻度 —— 用户答：不是柱子，是**刻度标签**。
    --      根因在 `buildTickRow` 的**等步长抽稀**：
    --        它用 `labels[#labels]`（**最后一格**）量宽度算 stride，
    --        而不是量**最宽那格**；累计视图的标签是 41 轮之前的 7 字
    --        `25年11月`（842px 图宽）⇒ `stride = ceil((84+15)/70.17) = 2`
    --        ⇒ 保留 1,3,5,7,9,11 号桶 ⇒ 丢掉 12 月。
    --        复现出的刻度正是 `25年11月|26年01月|…|26年09月`，
    --        与用户「只显示11月 26年1月」**完全对上**。
    --      改法：换成**从左到右贪心打包**（`min_gap = scaleBySize(4)`），
    --        并加两条**保底**：跨年那格（含「年」字）和**最后一格**永不被丢；
    --        若保底格与前一格重叠，则撤掉前一格（`table.remove(items)`）。
    --        实测：累计视图 12/12 刻度全放下（含 12 月），年视图 12/12，
    --        极窄时退化成 `26年01月|04月|07月|10月`（仍保住跨年格 + 末格）。
    --
    --   ③ 【bug】进了「阅读字数」视图就回不到柱状图 —— 用户答：两条路径都中招。
    --      根因：趋势页那两个 `IconButton` 没关 `allow_flash`。
    --        `IconButton:onTapIconButton()` 的默认分支会在 callback 前后各做一次
    --        `setDirty(nil, "fast", self.dimen)` + `forceRePaint()`，
    --        其中**尾随那次**在队列里留了一个「图标小矩形」的刷新区域 ⇒
    --        `_repaint()` 末尾的「整屏兜底」判断 `not self._refresh_stack[1]`
    --        永远为假 ⇒ 兜底不触发 ⇒ callback 跑了（状态真的变了）但屏幕没重画。
    --      改法：两个都加 `allow_flash = false` ⇒ 直接走 `self.callback()`。
    --
    --   ④ 【bug】日/周切换时年月日两行闪一下黑框再消失 ——
    --      根因：`reload()` 里 `UIManager:close(self)` + `UIManager:show(next)`
    --        **都没带刷新类型** ⇒ `_refresh` 直接 return（什么都不入队）⇒
    --        `_repaint()` 走到兜底 `self:_refresh("partial")`，
    --        **而 partial 无区域会被提升为 `"full"`**（uimanager.lua:1163-1175）
    --        ⇒ 整屏黑闪。
    --      改法：`UIManager:show(next_page, "ui", self.popup_frame.dimen)` ——
    --        显式带区域、且 `"ui"` **不在提升名单里**，兜底不再触发。
    --      ★ 为什么能安全复用 `self.popup_frame.dimen`：弹窗唯一子控件是
    --        `FixedPane`（ScrollableContainer），它**永远有 dimen**
    --        （frame_w × available_h），而 `WidgetContainer:getSize()` 有 dimen
    --        就直接返回 ⇒ 弹窗尺寸**与内容高度无关** ⇒ 每个视图里
    --        `CenterContainer` 都把它居中到同一位置，区域可信。
    --
    --   ⑤ 【顺手发现的 2 个潜伏 bug】`buildViewTabs`（4 个视图切换标签）：
    --      · 没套 `FixedBox` ⇒ `FrameContainer:getSize()` **不看 `self.width`**，
    --        它按 `self[1]:getSize().w + (margin+bordersize)*2 + padding` 算
    --        （upstream framecontainer.lua:54-67）⇒ 返回 `230 + 2*2 = 234`，
    --        而 `paintTo` 用的是 `self.width`（:115）= **230**，差 4px。
    --        `HorizontalGroup` 按每个子控件的 `getSize().w` 递进 ⇒ 布局递进
    --        243px、布局框 `4*234 + 3*9 = 963px`，而内容区只有 **950px**。
    --        因为父级是 `align="left"`，整排往右挤：**左边距 18px、
    --        右边距只剩 9px**（格子之间还多出 4px 幽灵间距）。
    --        ⇒ 症状是**4 个标签整体右偏、不对称**，不是被裁掉。
    --        改成外面套 `FixedBox{ width = cell_w, height = cell_h }` 后
    --        `getSize()` 返回 230 ⇒ 递进 239px、整排 `4*230 + 3*9 = 947 ≤ 950` ✓。
    --      · 边框色字段写成了 `bordercolor`，而 FrameContainer 认的是
    --        **`color`**（framecontainer.lua:29 声明 `color`，:139 把
    --        `self.color` 传给 paintBorder）⇒ 边框色**被静默忽略**。已改正。
    --        （本文件另有 5 处 `bordercolor`，43 轮**故意没动**：都传黑色 =
    --          默认值，改名零行为差异、徒增无关 diff。grep 得到
    --          2223 / 2361 / 2712 / 3051 / 3489。）
