    --   ⇒ 与「总览 / 阅读趋势 / 阅读字数 / 阅读速度」共用同一条分段轨道，
    --     不另开入口。日历页自上而下：
    --       视图轨道（5 格）
    --       指标轨道：字数 / 速度 / 时间        ← `CAL_METRICS`
    --       写法轨道：自动 / k / 万              ← `CAL_FORMATS`，
    --                                            **只在 metric == "units" 时出现**
    --                                            （「速度」「时间」没有 k/万 这回事）
    --       ‹  2026 年 10 月  ›                  ← 前后各挪 1 个月，跨年自动进位
    --       一 二 三 四 五 六 日（周一起始）
    --       日期格子：日期数字 + 当天数值；今天那格黑底白字
    --   每格点一下 ⇒ `reload{ period = "day", anchor = 那天 }`，
    --   与日选择器 `showDayPicker` 的行为一致。
