    --     **文件后半**的选择器一节 ⇒ 必须像 45f/46 那样在 `local SolidRect` /
    --     `local HRule` 之后加**前向声明** `local anchorAtMonth`，并把定义写成
    --     `anchorAtMonth = function(...)`（**不能**写 `local function`，
    --     否则会另起一个新 local、前向声明失效）。
