    -- ★★★ 1.1 内修订（52：导航栏选中改回纯黑 + 日历格子填充/文字修复 + 年月两行）
    -- =====================================================================
    --
    -- 用户原话（三件事）：
    --   「选中的导航栏还是深色吧，不要再闪烁了，另外日历页面的显示的内容不完全」
