    --   52 那版给每格加了 1px 深灰细边（为了让「白底压白卡片」的格子看得见），
    --   但相邻两格的边叠在一起就是 2px 线 ⇒ 整张日历被切成一张网。
    --   用户不要这个，去掉：`calendarCell` 不再传 `border_size` / `border_color`。
